final class MetalFighterV6View extends BaseArcadeView {
  private final ArcadeFx fx=new ArcadeFx();private final Random rnd=new Random(6606L);
  private float x=205,ex=748,vx,evx,y,ey,vy,evy,ai,atk,eAtk,specialCd,hitFlash,shake,roundClock=65,comboTimer,special=30,hitStop,intro=1.8f,koTimer,enemyBlock,parryWindow,stun,eStun;
  private int hp=100,ehp=100,score,round=1,pWins,eWins,combo,pAttack,eAttack,facing=1,eFacing=-1,opponent=0,careerWins,stage=0;
  private boolean left,right,block,punch,kick,arc,jump,jumpLatch,ground=true,eGround=true,prevBlock,throwLatch;
  private final RectF bL=new RectF(18,432,110,524),bR=new RectF(116,432,208,524),bJ=new RectF(214,432,316,524),bP=new RectF(566,426,660,524),bK=new RectF(665,426,759,524),bB=new RectF(764,426,858,524),bA=new RectF(863,420,958,524);
  private static final String[] OPP={"KÓKLER KONTÁR","ACÉL MEDVE","ÍVÁRNYÉK","MŰHELY BAJNOK"};
  MetalFighterV6View(Context c,GateCraftGame o){super(c,o);}
  @Override public int score(){return score;}@Override public int level(){return opponent+1;}@Override public int lives(){return Math.max(1,3-eWins);}@Override public void shutdown(){super.shutdown();fx.clear();}
  @Override public void restart(){x=205;ex=748;y=ey=0;vy=evy=0;hp=ehp=100;vx=evx=0;specialCd=hitFlash=shake=atk=eAtk=hitStop=koTimer=parryWindow=stun=eStun=0;left=right=block=punch=kick=arc=jump=false;ground=eGround=true;roundClock=65;combo=0;comboTimer=0;special=Math.max(20,special);intro=1.6f;invalidate();}
  private float oppSpeed(){return 165+opponent*22;}private int oppDmg(){return 11+opponent*3;}private String oppName(){return OPP[Math.max(0,Math.min(OPP.length-1,opponent))];}

  @Override void updateGame(float dt){fx.update(dt);if(hitStop>0){hitStop=Math.max(0,hitStop-dt);return;}intro=Math.max(0,intro-dt);koTimer=Math.max(0,koTimer-dt);specialCd=Math.max(0,specialCd-dt);hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt);atk=Math.max(0,atk-dt);eAtk=Math.max(0,eAtk-dt);comboTimer=Math.max(0,comboTimer-dt);parryWindow=Math.max(0,parryWindow-dt);stun=Math.max(0,stun-dt);eStun=Math.max(0,eStun-dt);if(comboTimer<=0)combo=0;if(intro>0||koTimer>0)return;roundClock=Math.max(0,roundClock-dt);special=Math.min(100,special+dt*(4+careerWins*.2f));
    float sp=305;if(stun<=0){if(left)vx=-sp;else if(right)vx=sp;else vx*=Math.pow(.0008,dt);if(jump&&!jumpLatch&&ground){vy=-565;ground=false;jumpLatch=true;fx.dust(x,385,8,Color.rgb(92,88,82));}if(!jump)jumpLatch=false;}else vx*=.84f;if(!ground){vy+=1360*dt;y+=vy*dt;if(y>=0){y=0;vy=0;ground=true;fx.dust(x,388,8,Color.rgb(98,93,84));}}x+=vx*dt;x=Math.max(62,Math.min(898,x));facing=x<=ex?1:-1;eFacing=-facing;
    if(eStun<=0){ai-=dt;if(ai<=0){ai=.12f+rnd.nextFloat()*.22f;float d=x-ex,ad=Math.abs(d);if(ad>170)evx=(d>0?1:-1)*oppSpeed();else{evx*=.2f;float r=rnd.nextFloat();if(r<.12f+opponent*.03f)enemyBlock=.28f;else if(r<.20f&&eGround){evy=-500;eGround=false;}else if(r<.70f)enemyStrike(rnd.nextFloat()<.34f?2:1);else if(opponent>=2&&r>.86f)enemySpecial();}}}else evx*=.75f;enemyBlock=Math.max(0,enemyBlock-dt);if(!eGround){evy+=1360*dt;ey+=evy*dt;if(ey>=0){ey=0;evy=0;eGround=true;}}ex+=evx*dt;ex=Math.max(62,Math.min(898,ex));evx*=Math.pow(.05,dt);
    if(Math.abs(x-ex)<74&&Math.abs(y-ey)<65){float mid=(x+ex)/2;if(x<ex){x=Math.min(x,mid-38);ex=Math.max(ex,mid+38);}else{x=Math.max(x,mid+38);ex=Math.min(ex,mid-38);}}
    if(punch&&kick&&!throwLatch){throwLatch=true;doThrow();punch=kick=false;}if(!punch&&!kick)throwLatch=false;if(punch){punch=false;strike(10,104,1,.23f);}if(kick){kick=false;strike(16,130,2,.32f);}if(arc){arc=false;if(specialCd<=0&&special>=60){special-=60;specialCd=2.0f;strike(30+opponent,250,3,.48f);fx.sparks(x+facing*78,318+y,30,Color.rgb(100,202,255));}}
    if(roundClock<=0){if(hp>=ehp)ehp=0;else hp=0;}if(ehp<=0)roundWin();else if(hp<=0)roundLose();
  }

  private void strike(int dmg,float range,int kind,float duration){if(atk>0||stun>0)return;pAttack=kind;atk=duration;if(Math.abs(x-ex)<=range&&Math.abs(y-ey)<84){if(enemyBlock>0&&kind!=3){ehp-=3;special=Math.min(100,special+4);fx.sparks(ex-facing*24,317+ey,8,Color.rgb(196,211,230));return;}int dealt=dmg+(combo>=2?3:0)+(careerWins/3);ehp-=dealt;ex+=facing*(kind==2?30:kind==3?48:19);eStun=kind==3?.26f:.09f;hitFlash=.10f;shake=kind==3?.22f:.09f;hitStop=kind==3?.065f:.035f;combo++;comboTimer=.92f;special=Math.min(100,special+9);score+=dealt*(5+combo);owner.reportScore(score);fx.sparks(ex-facing*22,316+ey,kind==3?28:12,kind==3?Color.rgb(105,205,255):Color.rgb(255,192,70));}}
  private void doThrow(){if(atk>0||Math.abs(x-ex)>82||Math.abs(y-ey)>70)return;atk=.45f;pAttack=4;ehp-=18+careerWins/4;ex+=facing*62;eStun=.35f;combo=0;special=Math.min(100,special+12);shake=.13f;hitStop=.05f;fx.sparks(ex,320,16,Color.rgb(255,174,77));}
  private void enemyStrike(int kind){if(eAtk>0||eStun>0)return;eAttack=kind;eAtk=kind==2?.36f:.26f;if(Math.abs(x-ex)<(kind==2?128:104)&&Math.abs(y-ey)<84){if(parryWindow>0){eStun=.42f;special=Math.min(100,special+18);score+=150;fx.sparks(x+facing*28,318+y,18,Color.rgb(110,215,255));parryWindow=0;return;}int d=kind==2?oppDmg()+5:oppDmg();if(block){d=4;special=Math.min(100,special+5);fx.sparks(x-facing*28,320+y,8,Color.rgb(190,210,230));}hp-=d;x-=facing*(block?5:20);stun=.08f;hitFlash=.10f;shake=.08f;hitStop=.03f;combo=0;fx.sparks(x+facing*22,317+y,9,Color.rgb(255,145,55));}}
  private void enemySpecial(){if(eAtk>0)return;eAttack=3;eAtk=.48f;if(Math.abs(x-ex)<235&&Math.abs(y-ey)<90){if(block){hp-=6;special=Math.min(100,special+8);}else{hp-=18+opponent*2;stun=.18f;}shake=.14f;fx.sparks(x,310+y,20,opponent==3?Color.rgb(255,95,55):Color.rgb(160,95,255));}}
  private void roundWin(){if(koTimer>0)return;pWins++;score+=700+Math.max(0,(int)roundClock)*8;owner.reportScore(score);koTimer=1.2f;if(pWins>=2){careerWins++;opponent++;stage=(stage+1)%4;pWins=eWins=0;if(opponent>=4){opponent=0;score+=2500;owner.reportGameComplete(score);}special=Math.min(100,special+20);}mainReset();}
  private void roundLose(){if(koTimer>0)return;eWins++;score=Math.max(0,score-180);owner.reportGameOver(score);koTimer=1.2f;if(eWins>=2){eWins=pWins=0;special=Math.max(20,special-15);}mainReset();}
  private void mainReset(){x=205;ex=748;y=ey=0;vy=evy=vx=evx=0;hp=ehp=100;roundClock=65;round++;intro=1.5f;combo=0;stun=eStun=0;}

  @Override void drawGame(Canvas c){float sh=shake>0?(float)Math.sin(System.currentTimeMillis()*.08)*7:0;c.save();c.translate(sh,0);drawStage(c);fighter(c,x,389+y,false,facing,pAttack,atk,block);fighter(c,ex,389+ey,true,eFacing,eAttack,eAtk,enemyBlock>0);fx.draw(c,p);if(hitFlash>0)fill(c,Color.argb(55,255,235,175),0,74,960,410);c.restore();
    fill(c,Color.rgb(7,7,11),0,0,960,77);text(c,"METAL FIGHTER '99",480,29,26,Color.rgb(248,211,80),Paint.Align.CENTER,true);text(c,t("LAKATOS SZAKI","METALWORKER","METALLBAUER","HERRERO","MÉTALLIER","金属工","FABBRO","SERRALHEIRO","ŚLUSARZ","METAALBEWERKER","LĂCĂTUȘ","СЛЕСАРЬ"),18,61,13,Color.WHITE,Paint.Align.LEFT,true);text(c,oppName(),942,61,13,Color.WHITE,Paint.Align.RIGHT,true);bar(c,18,9,hp,Color.rgb(57,194,75),false);bar(c,662,9,ehp,Color.rgb(211,59,46),true);text(c,"R"+round+"  "+Math.max(0,(int)roundClock)+"   "+pWins+"-"+eWins,480,60,17,Color.WHITE,Paint.Align.CENTER,true);fill(c,Color.rgb(31,30,37),345,11,615,19);fill(c,Color.rgb(112,65,164),347,13,347+266*special/100f,17);text(c,"SUPER "+(int)special+"%",480,18,10,Color.rgb(214,190,255),Paint.Align.CENTER,true);if(combo>=2)text(c,"COMBO x"+combo,480,96,22,Color.rgb(255,201,63),Paint.Align.CENTER,true);if(intro>0)text(c,intro>.8?"ROUND "+round:"FIGHT!",480,235,intro>.8?42:50,Color.rgb(255,221,81),Paint.Align.CENTER,true);if(koTimer>0)text(c,"K.O.",480,235,58,Color.rgb(255,91,62),Paint.Align.CENTER,true);
    arcadeButton(c,bL,"◀",Color.rgb(45,99,158),left);arcadeButton(c,bR,"▶",Color.rgb(45,99,158),right);arcadeButton(c,bJ,"▲",Color.rgb(45,99,158),jump);arcadeButton(c,bP,t("ÜT","HIT","HIEB","GOLPE","COUP","拳","COLPO","SOCO","CIOS","SLAG","LOV","УДАР"),Color.rgb(169,58,43),touched(bP));arcadeButton(c,bK,t("RÚG","KICK","TRITT","PATADA","PIED","踢","CALCIO","CHUTE","KOP","TRAP","PICIOR","ПИНОК"),Color.rgb(178,91,35),touched(bK));arcadeButton(c,bB,t("VÉD","BLOCK","BLOCK","BLOQ","BLOC","防御","PARA","DEF","BLOK","BLOK","BLOC","БЛОК"),Color.rgb(54,101,139),block);arcadeButton(c,bA,(special>=60&&specialCd<=0)?t("SZUPER","SUPER","SUPER","SUPER","SUPER","超必杀","SUPER","SUPER","SUPER","SUPER","SUPER","СУПЕР"):"…",Color.rgb(119,65,165),touched(bA));
  }

  private void drawStage(Canvas c){int s=stage%4;if(s==0){fill(c,Color.rgb(26,17,31),0,0,960,540);fill(c,Color.rgb(76,42,91),0,74,960,238);for(int bx=-30;bx<1000;bx+=145){fill(c,Color.rgb(39,34,37),bx,190,bx+76,392);fill(c,Color.rgb(102,70,43),bx+8,205,bx+19,392);fill(c,Color.rgb(13,15,19),bx+29,246,bx+64,392);}fill(c,Color.rgb(232,84,29),446,305,521,365);}else if(s==1){fill(c,Color.rgb(13,25,31),0,0,960,540);for(int x=0;x<960;x+=86){fill(c,Color.rgb(37,63,72),x,120,x+52,390);line(c,Color.rgb(92,151,166),5,x+8,140,x+42,140);}for(int i=0;i<8;i++)fill(c,Color.rgb(210,158,48),80+i*118,275,112+i*118,390);}else if(s==2){fill(c,Color.rgb(43,24,18),0,0,960,540);fill(c,Color.rgb(108,57,29),0,80,960,250);for(int i=0;i<11;i++){line(c,Color.rgb(68,63,57),8,i*98,130,i*98+45,390);fill(c,Color.rgb(231,93,32),i*98+25,300,i*98+55,365);}}else{fill(c,Color.rgb(12,14,19),0,0,960,540);for(int x=0;x<960;x+=120){fill(c,Color.rgb(54,60,66),x,105,x+72,390);fill(c,Color.rgb(169,128,41),x+12,130,x+60,143);}text(c,"CHAMPIONSHIP",480,170,32,Color.rgb(235,197,65),Paint.Align.CENTER,true);}fill(c,Color.rgb(42,50,58),0,358,960,540);for(int yy=360;yy<540;yy+=23)line(c,Color.rgb(25,31,37),2,0,yy,960,yy);for(int bx=-120;bx<1080;bx+=56)line(c,Color.rgb(67,77,84),2,bx,358,bx+155,540);line(c,Color.rgb(182,135,49),4,0,394,960,394);}
  private void bar(Canvas c,float bx,float by,int v,int col,boolean rev){float w=280;fill(c,Color.rgb(40,35,31),bx,by,bx+w,by+19);float f=Math.max(0,v)/100f;if(rev)fill(c,col,bx+w-w*f+2,by+2,bx+w-2,by+17);else fill(c,col,bx+2,by+2,bx+2+(w-4)*f,by+17);stroke(c,Color.rgb(234,220,170),2,bx,by,bx+w,by+19);}
  private void fighter(Canvas c,float px,float gy,boolean enemy,int face,int attack,float timer,boolean def){int state=def?3:timer>0?2:Math.abs(enemy?evx:vx)>40?1:0;float phase=(System.currentTimeMillis()%1000)/1000f;SpriteKit.worker(c,p,px,gy,1.9f,face,state,phase,enemy);if(timer>0){float d=face>=0?1:-1;if(attack==1)fill(c,enemy?Color.rgb(196,145,101):Color.rgb(224,174,113),px+d*18,gy-85,px+d*54,gy-69);else if(attack==2)line(c,Color.rgb(47,49,55),12,px+d*8,gy-36,px+d*58,gy-53);else if(attack==3){line(c,enemy?Color.rgb(255,106,78):Color.rgb(94,194,255),12,px+d*32,gy-88,px+d*142,gy-111);line(c,Color.WHITE,3,px+d*36,gy-88,px+d*142,gy-111);}else if(attack==4){line(c,Color.rgb(238,183,67),10,px+d*10,gy-70,px+d*65,gy-45);}}}

  private void sync(){left=touched(bL);right=touched(bR);jump=touched(bJ);boolean nb=touched(bB);if(nb&&!prevBlock)parryWindow=.12f;prevBlock=nb;block=nb;}
  @Override void onGameDown(float tx,float ty){sync();if(in(bP,tx,ty))punch=true;if(in(bK,tx,ty))kick=true;if(in(bA,tx,ty))arc=true;}
  @Override void onGameMove(float tx,float ty){sync();}
  @Override void onGameUp(float tx,float ty){sync();if(!touched(bP))punch=false;if(!touched(bK))kick=false;}
}
